            "explanation": "U.P.P.C.S. (Pre) 2017\n\nिवत्त वषर् 2017-18 के केंद्रीय बजट की दस मुख्य िवषय वस्तुएं थीं– िकसान,\nग्रामीण आबादी, युवा, गरीब तथा िवशेष सुिवधाओं से वंिचत वगर्, अवसंरचना,\nिवत्तीय क्षेत्र, िडिजटल अथर्व्यवस्था, सावर्जिनक सेवा, िववेकपूणर् राजकोषीय\nप्रबंधन तथा कर प्रशासन। ‘िनयार्त िनष्पादन’ इसमें सिम्मिलत नहीं था।\nिवत्त वषर् 2025-26 के केंद्रीय बजट की िवषयवस्तु (Theme) के तहत\n‘िवकिसत भारत’ की संकल्पना में शािमल थे :\na. गरीबी से मुिक्त;\nb. शत-प्रितशत अच्छे स्तर की स्कूली िशक्षा;\nc. बेहतरीन‚ सस्ती और सवर्सुलभ स्वास्थ्य सेवाओं तक पहुंच;\nd. शत-प्रितशत कुशल कामगार के साथ साथर्क रोजगार;\ne. आिथर्क गितिविधयों में 70 प्रितशत मिहलाएं; और\nf. हमारे देश को ‘फूड बास्केट ऑफ िद वल्डर्’ बनाने वाले िकसान।\nकेंद्रीय बजट‚ 2026-27 को िवत्त मंत्री के बजट भाषण में ‘युवा शिक्त-\nसंचािलत’ बजट की संज्ञा देते हुए गरीब, शोिषत एवं वंिचतों पर ध्यान देने के\n‘संकल्प’ को पूरा करने हेतु िनम्निलिखत 3 कतर्व्यों से प्रेिरत बताया गया है :"
