            "correctAnswer": 0,
            "explanation": "U.P.P.C.S. (Mains) 2017\nसावर्जिनक व्ययों में अपव्ययता में कमी लाए जाने की तकनीक शून्य आधािरत\nबजट (Zero Base Budgeting) है। इस प्रकार की प्रणाली (तकनीक) में\nप्रत्येक िक्रया के िलए शून्य आधार पता िकया जाता है। तत्पश्चात िक्रया\nकरने के पहले प्रत्येक िक्रया का मूल्यांकन नई िक्रया के रूप में िकया जाता है।\nशून्य आधािरत बजट प्रणाली (ZBB System) व्यय होने के बाद पुनिनर्रीक्षण\nया अंकेक्षण द्वारा िनयंत्रण पर आधािरत नहीं है, बिल्क सावर्जिनक व्यय के\nहोने के पूवर् ही उसकी उत्पादकता, उपयोिगता या आवश्यकता के परीक्षण\nपर आधािरत है। सावर्जिनक बजिटंग के क्षेत्र में शून्य आधािरत बजट का\nप्रयोग वषर् 1973 में िजम्मी काटर्र द्वारा िकया गया, जब वे जािजर्या (संयुक्त\nराज्य अमेिरका) के गवनर्र थे। हालांिक इस तकनीक के प्रवतर्क पीटर ए.\nपायर हैं। भारत में इस प्रणाली की शुरुआत वषर् 1986 में सावर्जिनक बजट\nके िनधार्रण के संबंध में की गई।"
